export const D9_ENH_T1_S1: PracticeQ[] = [
  q("d9h-001","d9-t1-s1","'There is' kab use karte hain?","mcq","Singular noun ya uncountable noun ke sath (present tense)","There IS = singular subject in present. There IS a book (singular). There IS water (uncountable).","There is = singular ya uncountable ke sath. There are = plural ke sath.",5,{a:"Plural nouns ke sath",b:"Past tense mein",c:"Singular noun ya uncountable noun ke sath (present tense)",d:"Kisi bhi noun ke sath"}),
  q("d9h-002","d9-t1-s1","'Mere school mein ek library hai.' ko translate karo.","translation","There is a library in my school.","There is + singular noun (a library). In my school = where it exists.","There is + singular. A library = singular noun.",5,undefined,[{word:"there is a library",meaning:"ek library hai"},{word:"in my school",meaning:"mere school mein"}]),
  q("d9h-003","d9-t1-s1","'Is kamre mein koi nahi hai.' ko translate karo.","translation","There is nobody in this room.","There is + nobody = singular negative existence. In this room = is kamre mein.","There is nobody = singular negative. Is kamre mein = in this room.",5,undefined,[{word:"there is nobody",meaning:"koi nahi hai"},{word:"in this room",meaning:"is kamre mein"}]),
  q("d9h-004","d9-t1-s1","Fill: '___ a problem with the computer.'","fill_blank","There is","A problem = singular. Present tense = There is a problem.","A problem = singular present. There is.",5,undefined,[{word:"there is a problem",meaning:"ek problem hai"}]),
  q("d9h-005","d9-t1-s1","'Hamare office mein koi printer nahi hai.' ko translate karo.","translation","There is no printer in our office.","There is no + singular noun. Negative existence = There is no.","There is no + singular noun = negative existence.",5,undefined,[{word:"there is no printer",meaning:"koi printer nahi hai"},{word:"in our office",meaning:"hamare office mein"}]),
  q("d9h-006","d9-t1-s1","'Hamare colony mein bahut saare shops hain.' ko translate karo.","translation","There are many shops in our colony.","Many shops = plural. Present = There are. Many shops = plural noun.","There are + plural noun. Many shops = bahut saare shops.",5,undefined,[{word:"there are many shops",meaning:"bahut saare shops hain"},{word:"in our colony",meaning:"hamare colony mein"}]),
  q("d9h-007","d9-t1-s1","Error: 'There are a big tree in the garden.'","error_detection","There is a big tree in the garden.","'A big tree' = singular. Singular noun takes 'is', not 'are'.","A big tree = singular. There IS (not are). Are = plural ke sath.",5,{a:"There are a big tree in the garden.",b:"There is big tree in the garden.",c:"There is a big tree in the garden.",d:"There were a big tree in the garden."}),
  q("d9h-008","d9-t1-s1","'Kya tumhare ghar mein garden hai?' — translate.","translation","Is there a garden at your house?","Question: Is there + singular? Is there a garden = correct question form.","Is there = singular question. A garden = singular noun.",5,undefined,[{word:"is there a garden",meaning:"kya garden hai"},{word:"at your house",meaning:"tumhare ghar mein"}]),
  q("d9h-009","d9-t1-s1","'Tez traffic ke baad koi accident tha.' ko translate karo.","translation","There was an accident after the heavy traffic.","Past tense + singular accident = There was. After the heavy traffic = tez traffic ke baad.","There was + singular noun = past existence.",5,undefined,[{word:"there was an accident",meaning:"ek accident tha"},{word:"after the heavy traffic",meaning:"tez traffic ke baad"}]),
  q("d9h-010","d9-t1-s1","'1990 mein is jagah par koi building nahi thi.' ko translate karo.","translation","There was no building in this place in 1990.","Past negative existence: There was no + singular. In 1990 = past time marker.","There was no + singular = past negative. In 1990 = past time.",5,undefined,[{word:"there was no building",meaning:"koi building nahi thi"},{word:"in 1990",meaning:"1990 mein"}]),
];

