export const D11_ENH_T1_S1: PracticeQ[] = [
  q("d11h-001","d11-t1-s1","'Want to' ke baad kaun si verb form aati hai?","mcq","Base form of the verb (V1 — infinitive without 'to')","Want to + V1 (base form). I want to go. She wants to eat. Base verb, not V2/V3.","Want to + base verb. I want to GO (not went/gone).",5,{a:"V2 (past simple)",b:"V3 (past participle)",c:"Base form of the verb (V1 — infinitive without 'to')",d:"Verb + ing"}),
  q("d11h-002","d11-t1-s1","'Main English fluently bolna chahta hun.' ko translate karo.","translation","I want to speak English fluently.","I want to + speak (base form) + fluently. Simple want + infinitive structure.","I want to speak = want to + base verb. Fluently = adverb.",5,undefined,[{word:"I want to speak",meaning:"main bolna chahta hun"},{word:"fluently",meaning:"dhara pravah"}]),
  q("d11h-003","d11-t1-s1","'She ___ (want) to become a doctor.' — fill in correct form.","fill_blank","wants","She = singular third person. Add -s to 'want' → wants. Wants to + base verb.","She = singular. Want + s = wants. Wants to become = correct.",5,undefined,[{word:"wants to become",meaning:"banna chahti hai"}]),
  q("d11h-004","d11-t1-s1","'Woh log new job dhundhna chahte hain.' ko translate karo.","translation","They want to find a new job.","They = plural. Want (no -s). Want to + find (base verb). A new job = object.","They want to find = plural want to + base verb.",5,undefined,[{word:"they want to find",meaning:"dhundhna chahte hain"},{word:"a new job",meaning:"naya kaam"}]),
  q("d11h-005","d11-t1-s1","Error: 'He want to learns English grammar perfectly.'","error_detection","He wants to learn English grammar perfectly.","Two errors: want → wants (singular) AND learns → learn (base verb after 'to').","He wants (singular). To learn (base verb after 'to'). Not 'to learns'.",5,{a:"He want to learns English grammar perfectly.",b:"He wants to learns English grammar perfectly.",c:"He want to learn English grammar perfectly.",d:"He wants to learn English grammar perfectly."}),
  q("d11h-006","d11-t1-s2","'Mujhe coffee chahiye.' ko translate karo.","translation","I want some coffee.","I want + noun (coffee). Want can directly precede a noun object.","I want + noun = direct object. Some coffee = uncountable.",5,undefined,[{word:"I want some coffee",meaning:"mujhe coffee chahiye"}]),
  q("d11h-007","d11-t1-s2","'Woh chahti hai ki uska beta doctor bane.' ko translate karo.","translation","She wants her son to become a doctor.","Want + object + to + base verb: She wants [her son] [to become] a doctor.","She wants + her son (object) + to become = want + object + infinitive.",8,undefined,[{word:"she wants her son to become",meaning:"chahti hai ki beta bane"},{word:"a doctor",meaning:"doctor"}]),
  q("d11h-008","d11-t1-s2","Fill: 'My teacher wants us ___ (practice) every day.'","fill_blank","to practice","Want + object + TO + base verb. Us = object. To practice = infinitive.","Wants + us (object) + to practice = want + object + to + verb.",8,undefined,[{word:"wants us to practice",meaning:"chahti hai ki hum practice karein"}]),
  q("d11h-009","d11-t1-s3","'Main nahi chahta ki woh late aaye.' ko translate karo.","translation","I don't want him to be late.","Don't want + him (object) + to be + late (adjective). Negative want + object + infinitive.","Don't want + object + to + verb = negative want structure.",8,undefined,[{word:"I don't want him to be late",meaning:"nahi chahta ki woh late aaye"}]),
  q("d11h-010","d11-t1-s3","'What do you want to do this weekend?' — iss question ka ek creative jawab do.","translation","I want to go on a picnic with my friends.","Want + to go = want to + base verb. On a picnic = picnic par. With my friends = doston ke sath.","I want to go = want to + base verb. Complete sentence with detail.",5,undefined,[{word:"I want to go on a picnic",meaning:"main picnic par jana chahta hun"}]),
];

