export const D12_ENH_T1_S1: PracticeQ[] = [
  q("d12h-001","d12-t1-s1","'Wanted' ka use kab hota hai?","mcq","Past desires, past wishes, polite requests in present","Wanted = past tense of want. Use for: past desires, unfulfilled wishes, polite present requests.","Wanted = past desire. I wanted to go (past). Or politely: I wanted to ask you (present polite).",5,{a:"Sirf present desires ke liye",b:"Sirf future ke liye",c:"Past desires, past wishes, polite requests in present",d:"Future perfect ke liye"}),
  q("d12h-002","d12-t1-s1","'Main kal wahan jaana chahta tha.' ko translate karo.","translation","I wanted to go there yesterday.","Wanted to + go (base verb). Yesterday = past time marker.","Wanted to + base verb = past desire. Yesterday = past.",5,undefined,[{word:"I wanted to go",meaning:"main jaana chahta tha"},{word:"yesterday",meaning:"kal"}]),
  q("d12h-003","d12-t1-s1","'Woh doctor banna chahta tha lekin engineer bana.' ko translate karo.","translation","He wanted to become a doctor but became an engineer.","Wanted to become = past unfulfilled desire. But became = what happened instead.","Wanted to become = past unfulfilled wish. But became = jo hua.",8,undefined,[{word:"wanted to become a doctor",meaning:"doctor banna chahta tha"},{word:"but became an engineer",meaning:"lekin engineer bana"}]),
  q("d12h-004","d12-t1-s2","'Woh pahle se hi jaana chahti thi.' ko translate karo.","translation","She had wanted to leave all along.","Had wanted = past perfect form (wanted from even earlier). All along = pahle se hi.","Had wanted = Past Perfect want. All along = pahle se hi.",10,undefined,[{word:"had wanted to leave",meaning:"jaana chahti thi"},{word:"all along",meaning:"pahle se hi"}]),
  q("d12h-005","d12-t1-s2","Error: 'She wanted that he comes early today.'","error_detection","She wanted him to come early.","'Wanted him to come' = correct. Not 'wanted that he comes'. Wanted + object + to + base verb.","Wanted + him (object) + to come = correct. 'That he comes' = wrong.",5,{a:"She wanted that he comes early today.",b:"She wanted him coming early.",c:"She wanted him to come early.",d:"She want him to come early."}),
  q("d12h-006","d12-t1-s3","'Maine apni trip cancel nahi karna chaha tha.' ko translate karo.","translation","I didn't want to cancel my trip.","Didn't want to + cancel (base verb) = negative past desire.","Didn't want to + base verb = negative past want.",5,undefined,[{word:"didn't want to cancel",meaning:"cancel nahi karna chahta tha"},{word:"my trip",meaning:"meri trip"}]),
  q("d12h-007","d12-t1-s3","'Kya tum uss waqt wahin rehna chahte the?' — translate.","translation","Did you want to stay there at that time?","Did + you + want + to stay (base verb)? Past question with 'did'.","Did you want to stay = past question with did. At that time = uss waqt.",5,undefined,[{word:"did you want to stay",meaning:"kya tum rehna chahte the"},{word:"at that time",meaning:"uss waqt"}]),
  q("d12h-008","d12-t2-s1","'Main aapse ek cheez poochna chahta tha.' — translate (polite present).","translation","I wanted to ask you something.","'I wanted to ask' = polite form in present. Using 'wanted' makes it softer than 'I want to ask'.","Wanted to ask = polite present request. Softer than 'I want to ask'.",8,undefined,[{word:"I wanted to ask you",meaning:"main poochna chahta tha"},{word:"something",meaning:"ek cheez"}]),
  q("d12h-009","d12-t2-s1","'She wanted me to ___ (finish) the assignment before lunch.' — fill in.","fill_blank","finish","Wanted + me (object) + to + finish (base verb). Past want with object and infinitive.","Wanted + me + to + finish = want + object + to + base verb (past).",8,undefined,[{word:"wanted me to finish",meaning:"chahti thi ki main khatam karun"}]),
  q("d12h-010","d12-t2-s2","'Unhone request ki thi ki main unhe call karun.' ko translate karo.","translation","They wanted me to call them.","They wanted + me (object) + to call (infinitive) + them. Past want + object + infinitive.","Wanted + me (object) + to call = past want + object + infinitive.",8,undefined,[{word:"wanted me to call them",meaning:"chahte the ki main call karun"}]),
];

