// ─── Helper: Get enhanced questions for a specific day ────────
// Returns all enhanced questions for a day, optionally filtered by subtopicId
export function getDays8to14QuestionsEnhanced(
  dayNumber: number,
  subtopicId?: string
): PracticeQ[] {
  const dayMap: Record<number, PracticeQ[]> = {
    8: ALL_DAY_8_ENH_QUESTIONS,
    9: ALL_DAY_9_ENH_QUESTIONS,
    10: ALL_DAY_10_ENH_QUESTIONS,
    11: ALL_DAY_11_ENH_QUESTIONS,
    12: ALL_DAY_12_ENH_QUESTIONS,
    13: ALL_DAY_13_ENH_QUESTIONS,
    14: ALL_DAY_14_ENH_QUESTIONS,
  };

  const dayQuestions = dayMap[dayNumber] || [];

  if (subtopicId) {
    const filtered = dayQuestions.filter(q => q.subtopicId === subtopicId);
    return filtered.length > 0 ? filtered : dayQuestions;
  }
  return dayQuestions;
}
